def get_current_weather(location, **_extra):
    import json, os, datetime, re, math, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0026000" if __import__("os").path.isdir("./environment_mix/0026000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    def _parse_iso(s):
        if s is None:
            return None
        if isinstance(s, str):
            try:
                if s.endswith("Z"):
                    return datetime.datetime.fromisoformat(s[:-1])
                return datetime.datetime.fromisoformat(s)
            except ValueError:
                return None
        return None

    def _within_supported_us(lat, lon):
        # Broad coverage bounds for US + territories + coastal waters (approx).
        # Reject obviously out-of-scope coordinates.
        return (-14.0 <= lat <= 72.0) and (-179.9 <= lon <= -60.0)

    def _haversine_km(lat1, lon1, lat2, lon2):
        r = 6371.0
        p = math.pi / 180.0
        dlat = (lat2 - lat1) * p
        dlon = (lon2 - lon1) * p
        a = (math.sin(dlat/2)**2 +
             math.cos(lat1*p) * math.cos(lat2*p) * (math.sin(dlon/2)**2))
        return 2 * r * math.asin(min(1.0, math.sqrt(a)))

    def _new_id(prefix):
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}"

    def _log_request(status, code, location_id=None, cache_hit=False, served_weather_product_id=None, error_message=None, latency_ms=None):
        reqs = _load("api_requests.json")
        rid = _new_id("req")
        row = {
            "id": rid,
            "tool_name": "get_current_weather",
            "location_raw": location if isinstance(location, str) else str(location),
            "location_id": location_id,
            "days": None,
            "hours": None,
            "limit": None,
            "severity": None,
            "response_status_code": int(code) if code is not None else None,
            "cache_hit": bool(cache_hit),
            "served_weather_product_id": served_weather_product_id,
            "latency_ms": int(latency_ms) if latency_ms is not None else None,
            "status": status,
            "error_message": error_message,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        reqs.append(row)
        _save("api_requests.json", reqs)

    # Validate input
    if not isinstance(location, str) or not location.strip():
        latency = int((time.time() - t0) * 1000)
        _log_request("rejected", 400, error_message="location must be a non-empty string", latency_ms=latency)
        return _err("VALIDATION_ERROR", "location must be a non-empty string")

    m = re.match(r"^\s*-?\d+(\.\d+)?\s*,\s*-?\d+(\.\d+)?\s*$", location)
    if not m:
        latency = int((time.time() - t0) * 1000)
        _log_request("rejected", 400, error_message="location must be coordinates 'lat,lng'", latency_ms=latency)
        return _err("VALIDATION_ERROR", "location must be coordinates 'lat,lng'")

    try:
        lat_s, lon_s = [x.strip() for x in location.split(",", 1)]
        lat = float(lat_s)
        lon = float(lon_s)
    except ValueError:
        latency = int((time.time() - t0) * 1000)
        _log_request("rejected", 400, error_message="location coordinates are not valid numbers", latency_ms=latency)
        return _err("VALIDATION_ERROR", "location coordinates are not valid numbers")

    if not (-90.0 <= lat <= 90.0) or not (-180.0 <= lon <= 180.0):
        latency = int((time.time() - t0) * 1000)
        _log_request("rejected", 400, error_message="latitude/longitude out of range", latency_ms=latency)
        return _err("VALIDATION_ERROR", "latitude/longitude out of range")

    if not _within_supported_us(lat, lon):
        latency = int((time.time() - t0) * 1000)
        _log_request("failed", 404, error_message="location outside supported US coverage", latency_ms=latency)
        return _err("NOT_FOUND", "location outside supported US coverage")

    # Resolve or create location row (unique(source,input_location_raw))
    locations = _load("locations.json")
    loc = None
    for r in locations:
        if r.get("source") == "coordinates" and r.get("input_location_raw") == location:
            loc = r
            break

    if loc is None:
        loc_id = _new_id("loc")
        loc = {
            "id": loc_id,
            "source": "coordinates",
            "input_location_raw": location,
            "latitude": lat,
            "longitude": lon,
            "state_code": None,
            "timezone": None,
            "coverage_type": "unknown",
            "status": "active",
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        # enforce unique(source,input_location_raw)
        for r in locations:
            if r.get("source") == loc["source"] and r.get("input_location_raw") == loc["input_location_raw"]:
                # Someone already created it; use existing to be idempotent
                loc = r
                break
        else:
            locations.append(loc)
            _save("locations.json", locations)

    location_id = loc.get("id")

    # Choose cache: newest by fetched_at for (location_id, kind='current', variant None), prefer fresh unexpired, else stale, else expired, else error
    products = _load("weather_products.json")
    candidates = [p for p in products if p.get("location_id") == location_id and p.get("kind") == "current" and (p.get("variant") is None)]
    def _sort_key(p):
        dt = _parse_iso(p.get("fetched_at")) or datetime.datetime.min
        return dt
    candidates.sort(key=_sort_key, reverse=True)

    selected = None
    cache_hit = False
    for p in candidates:
        if p.get("status") == "fresh":
            exp = _parse_iso(p.get("expires_at"))
            if exp is None or exp > now:
                selected = p
                cache_hit = True
                break
    if selected is None:
        for p in candidates:
            if p.get("status") == "stale":
                selected = p
                break
    if selected is None:
        for p in candidates:
            if p.get("status") == "expired":
                selected = p
                break
    if selected is None:
        for p in candidates:
            if p.get("status") == "error":
                selected = p
                break

    # Nearest active station (if any)
    stations = _load("stations.json")
    active_stations = [s for s in stations if s.get("status") == "active"]
    nearest_station = None
    if active_stations:
        best = None
        for s in active_stations:
            slat = s.get("latitude")
            slon = s.get("longitude")
            if isinstance(slat, (int, float)) and isinstance(slon, (int, float)):
                d = _haversine_km(lat, lon, float(slat), float(slon))
                if best is None or d < best[0]:
                    best = (d, s)
        if best is not None:
            nearest_station = dict(best[1])
            nearest_station["distance_km"] = best[0]

    if selected is None:
        latency = int((time.time() - t0) * 1000)
        _log_request("failed", 404, location_id=location_id, cache_hit=False, served_weather_product_id=None,
                     error_message="no cached current weather product available", latency_ms=latency)
        return _err("NOT_FOUND", "no cached current weather product available", location_id=location_id)

    latency = int((time.time() - t0) * 1000)
    _log_request("succeeded", 200, location_id=location_id, cache_hit=cache_hit,
                 served_weather_product_id=selected.get("id"), latency_ms=latency)

    return {
        "location": loc,
        "weather_product": selected,
        "nearest_station": nearest_station,
        "meta": {
            "cache_hit": cache_hit,
            "served_weather_product_id": selected.get("id"),
        }
    }

