    def _log_request(status, code, location_id=None, cache_hit=False, served_weather_product_id=None, error_message=None, latency_ms=None, days_val=None):
        reqs = _load("api_requests.json")
        rid = _new_id("req")
        row = {
            "id": rid,
            "tool_name": "get_weather_forecast",
            "location_raw": location if isinstance(location, str) else str(location),
            "location_id": location_id,
            "days": days_val,
            "hours": None,
            "limit": None,
            "severity": None,
            "response_status_code": int(code) if code is not None else None,
            "cache_hit": bool(cache_hit),
