        _log_request("rejected", 400, error_message="location must be a non-empty string", latency_ms=latency)
        return _err("VALIDATION_ERROR", "location must be a non-empty string")

    m = re.match(r"^\s*-?\d+(\.\d+)?\s*,\s*-?\d+(\.\d+)?\s*$", location)
    if not m:
        latency = int((time.time() - t0) * 1000)
        _log_request("rejected", 400, error_message="location must be coordinates 'lat,lng'", latency_ms=latency)
        return _err("VALIDATION_ERROR", "location must be coordinates 'lat,lng'")

    try:
        lat_s, lon_s = [x.strip() for x in location.split(",", 1)]
        lat = float(lat_s)
        lon = float(lon_s)
    except ValueError:
        latency = int((time.time() - t0) * 1000)
        _log_request("rejected", 400, error_message="location coordinates are not valid numbers", latency_ms=latency)
        return _err("VALIDATION_ERROR", "location coordinates are not valid numbers")

    if not (-90.0 <= lat <= 90.0) or not (-180.0 <= lon <= 180.0):
        latency = int((time.time() - t0) * 1000)
        _log_request("rejected", 400, error_message="latitude/longitude out of range", latency_ms=latency)
        return _err("VALIDATION_ERROR", "latitude/longitude out of range")

    if not _within_supported_us(lat, lon):
        latency = int((time.time() - t0) * 1000)
        _log_request("failed", 404, error_message="location outside supported US coverage", latency_ms=latency)
        return _err("NOT_FOUND", "location outside supported US coverage")

    # Validate days (clamp/validate to int 1..7; default 7)
    if days is None:
        days_i = 7
    else:
        if not isinstance(days, (int, float)) or isinstance(days, bool):
            latency = int((time.time() - t0) * 1000)
            _log_request("rejected", 400, error_message="days must be a number", latency_ms=latency)
            return _err("VALIDATION_ERROR", "days must be a number")
        days_i = int(days)
    if days_i < 1 or days_i > 7:
        latency = int((time.time() - t0) * 1000)
        _log_request("rejected", 400, error_message="days must be between 1 and 7", latency_ms=latency, days_val=days_i)
        return _err("VALIDATION_ERROR", "days must be between 1 and 7")

    # Resolve or create location row
    locations = _load("locations.json")
    loc = None
    for r in locations:
        if r.get("source") == "coordinates" and r.get("input_location_raw") == location:
            loc = r
            break
    if loc is None:
        loc = {
            "id": _new_id("loc"),
            "source": "coordinates",
            "input_location_raw": location,
            "latitude": lat,
            "longitude": lon,
            "state_code": None,
            "timezone": None,
            "coverage_type": "unknown",
            "status": "active",
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        for r in locations:
            if r.get("source") == loc["source"] and r.get("input_location_raw") == loc["input_location_raw"]:
                loc = r
                break
        else:
            locations.append(loc)
            _save("locations.json", locations)

    location_id = loc.get("id")
    variant = f"days={days_i}"

    # Cache selection
    products = _load("weather_products.json")
    candidates = [p for p in products if p.get("location_id") == location_id and p.get("kind") == "forecast_daily" and p.get("variant") == variant]
    candidates.sort(key=lambda p: _parse_iso(p.get("fetched_at")) or datetime.datetime.min, reverse=True)

    selected = None
    cache_hit = False
    for p in candidates:
        if p.get("status") == "fresh":
            exp = _parse_iso(p.get("expires_at"))
            if exp is None or exp > now:
                selected = p
                cache_hit = True
                break
    if selected is None:
        for p in candidates:
            if p.get("status") == "stale":
                selected = p
                break
    if selected is None:
        for p in candidates:
            if p.get("status") == "expired":
                selected = p
                break
    if selected is None:
        for p in candidates:
            if p.get("status") == "error":
                selected = p
                break

    if selected is None:
        latency = int((time.time() - t0) * 1000)
        _log_request("failed", 404, location_id=location_id, cache_hit=False, served_weather_product_id=None,
                     error_message="no cached daily forecast product available", latency_ms=latency, days_val=days_i)
        return _err("NOT_FOUND", "no cached daily forecast product available", location_id=location_id, days=days_i)

    # Trim payload periods if present
    payload = selected.get("payload")
    trimmed_payload = payload
    if isinstance(payload, dict):
        trimmed_payload = dict(payload)
        periods = payload.get("periods")
        if isinstance(periods, list):
            # days_i days includes day+night => up to 2*days_i periods
            trimmed_payload["periods"] = periods[: max(0, 2 * days_i)]

    latency = int((time.time() - t0) * 1000)
    _log_request("succeeded", 200, location_id=location_id, cache_hit=cache_hit,
                 served_weather_product_id=selected.get("id"), latency_ms=latency, days_val=days_i)

    served = dict(selected)
    served["payload"] = trimmed_payload

    return {
        "location": loc,
        "days": days_i,
        "weather_product": served,
        "meta": {
            "cache_hit": cache_hit,
            "served_weather_product_id": selected.get("id"),
            "variant": variant,
        }
    }

