            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    ALLOWED_STATE_CODES = {
        "AL","AK","AS","AR","AZ","CA","CO","CT","DE","DC","FL","GA","GU","HI","ID","IL","IN","IA","KS","KY","LA","ME",
        "MD","MA","MI","MN","MS","MO","MT","NE","NV","NH","NJ","NM","NY","NC","ND","OH","OK","OR","PA","PR","RI","SC",
        "SD","TN","TX","UT","VT","VI","VA","WA","WV","WI","WY","MP","PW","FM","MH"
    }
    ALLOWED_SEVERITY = {"all","extreme","severe","moderate","minor"}

    def _parse_iso(s):
        if s is None:
            return None
        if isinstance(s, str):
            try:
                if s.endswith("Z"):
                    return datetime.datetime.fromisoformat(s[:-1])
                return datetime.datetime.fromisoformat(s)
            except ValueError:
                return None
        return None

    def _within_supported_us(lat, lon):
        return (-14.0 <= lat <= 72.0) and (-179.9 <= lon <= -60.0)

    def _new_id(prefix):
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}"

    def _log_request(status, code, location_id=None, cache_hit=False, served_weather_product_id=None, error_message=None, latency_ms=None, severity_val=None):
        reqs = _load("api_requests.json")
        rid = _new_id("req")
        row = {
            "id": rid,
            "tool_name": "get_weather_alerts",
            "location_raw": location if isinstance(location, str) else str(location),
            "location_id": location_id,
            "days": None,
            "hours": None,
            "limit": None,
            "severity": severity_val,
            "response_status_code": int(code) if code is not None else None,
            "cache_hit": bool(cache_hit),
            "served_weather_product_id": served_weather_product_id,
            "latency_ms": int(latency_ms) if latency_ms is not None else None,
            "status": status,
            "error_message": error_message,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        reqs.append(row)
        _save("api_requests.json", reqs)

    # Validate severity
    if severity is None:
        severity_v = "all"
    else:
        if not isinstance(severity, str):
            latency = int((time.time() - t0) * 1000)
            _log_request("rejected", 400, error_message="severity must be a string", latency_ms=latency)
            return _err("VALIDATION_ERROR", "severity must be a string")
        severity_v = severity.strip().lower()

    if severity_v not in ALLOWED_SEVERITY:
        latency = int((time.time() - t0) * 1000)
        _log_request("rejected", 400, error_message="severity must be one of: all, extreme, severe, moderate, minor", latency_ms=latency, severity_val=severity_v)
        return _err("VALIDATION_ERROR", "severity must be one of: all, extreme, severe, moderate, minor")

    # Validate location
    if not isinstance(location, str) or not location.strip():
        latency = int((time.time() - t0) * 1000)
        _log_request("rejected", 400, error_message="location must be a non-empty string", latency_ms=latency, severity_val=severity_v)
        return _err("VALIDATION_ERROR", "location must be a non-empty string")

    loc_str = location.strip()
    is_coord = re.match(r"^\s*-?\d+(\.\d+)?\s*,\s*-?\d+(\.\d+)?\s*$", loc_str) is not None
    is_state = (len(loc_str) == 2 and loc_str.upper() in ALLOWED_STATE_CODES)

    location_id = None
    resolved_location = None
    filtered_alerts = []

    if is_state:
        state_code = loc_str.upper()
        # Filter active alerts by area_state_codes containment and not expired
        alerts = _load("alerts.json")
        for a in alerts:
            if a.get("status") != "active":
                continue
            exp = _parse_iso(a.get("expires_at"))
            if exp is not None and exp <= now:
                continue
            area = a.get("area_state_codes")
            if isinstance(area, list) and state_code in area:
                if severity_v != "all" and a.get("severity") != severity_v:
                    continue
                filtered_alerts.append(a)

        latency = int((time.time() - t0) * 1000)
        _log_request("succeeded", 200, location_id=None, cache_hit=False, served_weather_product_id=None,
                     latency_ms=latency, severity_val=severity_v)

        return {
            "query": {"type": "state_code", "state_code": state_code, "severity": severity_v},
            "alerts": filtered_alerts,
            "meta": {"count": len(filtered_alerts)}
        }

    if not is_coord:
        latency = int((time.time() - t0) * 1000)
        _log_request("rejected", 400, error_message="location must be coordinates 'lat,lng' or a valid 2-letter state/territory code", latency_ms=latency, severity_val=severity_v)
        return _err("VALIDATION_ERROR", "location must be coordinates 'lat,lng' or a valid 2-letter state/territory code")

    # Coordinate path: resolve/create location, then serve cached alerts weather_product variant 'severity=X'
    try:
        lat_s, lon_s = [x.strip() for x in loc_str.split(",", 1)]
        lat = float(lat_s)
        lon = float(lon_s)
    except ValueError:
        latency = int((time.time() - t0) * 1000)
        _log_request("rejected", 400, error_message="location coordinates are not valid numbers", latency_ms=latency, severity_val=severity_v)
        return _err("VALIDATION_ERROR", "location coordinates are not valid numbers")

    if not (-90.0 <= lat <= 90.0) or not (-180.0 <= lon <= 180.0):
        latency = int((time.time() - t0) * 1000)
        _log_request("rejected", 400, error_message="latitude/longitude out of range", latency_ms=latency, severity_val=severity_v)
        return _err("VALIDATION_ERROR", "latitude/longitude out of range")

    if not _within_supported_us(lat, lon):
        latency = int((time.time() - t0) * 1000)
        _log_request("failed", 404, error_message="location outside supported US coverage", latency_ms=latency, severity_val=severity_v)
        return _err("NOT_FOUND", "location outside supported US coverage")

    locations = _load("locations.json")
    for r in locations:
        if r.get("source") == "coordinates" and r.get("input_location_raw") == loc_str:
            resolved_location = r
            break
    if resolved_location is None:
        resolved_location = {
            "id": _new_id("loc"),
            "source": "coordinates",
            "input_location_raw": loc_str,
            "latitude": lat,
            "longitude": lon,
            "state_code": None,
            "timezone": None,
            "coverage_type": "unknown",
            "status": "active",
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        for r in locations:
            if r.get("source") == resolved_location["source"] and r.get("input_location_raw") == resolved_location["input_location_raw"]:
                resolved_location = r
                break
        else:
            locations.append(resolved_location)
            _save("locations.json", locations)

    location_id = resolved_location.get("id")
    variant = f"severity={severity_v}"

    products = _load("weather_products.json")
    candidates = [p for p in products if p.get("location_id") == location_id and p.get("kind") == "alerts" and p.get("variant") == variant]
    candidates.sort(key=lambda p: _parse_iso(p.get("fetched_at")) or datetime.datetime.min, reverse=True)

    selected = None
    cache_hit = False
    for p in candidates:
        if p.get("status") == "fresh":
            exp = _parse_iso(p.get("expires_at"))
            if exp is None or exp > now:
                selected = p
                cache_hit = True
                break
    if selected is None:
        for p in candidates:
            if p.get("status") == "stale":
                selected = p
                break
    if selected is None:
        for p in candidates:
            if p.get("status") == "expired":
                selected = p
                break
    if selected is None:
        for p in candidates:
            if p.get("status") == "error":
                selected = p
                break

    if selected is None:
        latency = int((time.time() - t0) * 1000)
        _log_request("failed", 404, location_id=location_id, cache_hit=False, served_weather_product_id=None,
                     error_message="no cached alerts product available", latency_ms=latency, severity_val=severity_v)
        return _err("NOT_FOUND", "no cached alerts product available", location_id=location_id, severity=severity_v)

    # Ensure payload list respects severity if payload is list-like of alerts
    payload = selected.get("payload")
    served_payload = payload
    if severity_v != "all":
        if isinstance(payload, dict) and isinstance(payload.get("alerts"), list):
            served_payload = dict(payload)
            served_payload["alerts"] = [a for a in payload["alerts"] if isinstance(a, dict) and a.get("severity") == severity_v]
        elif isinstance(payload, list):
            served_payload = [a for a in payload if isinstance(a, dict) and a.get("severity") == severity_v]

    served = dict(selected)
    served["payload"] = served_payload

    latency = int((time.time() - t0) * 1000)
    _log_request("succeeded", 200, location_id=location_id, cache_hit=cache_hit,
                 served_weather_product_id=selected.get("id"), latency_ms=latency, severity_val=severity_v)

    return {
        "location": resolved_location,
        "severity": severity_v,
        "weather_product": served,
        "meta": {
            "cache_hit": cache_hit,
            "served_weather_product_id": selected.get("id"),
            "variant": variant,
        }
    }

def get_local_time(location, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0026000" if __import__("os").path.isdir("./environment_mix/0026000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{os.urandom(6).hex()}"

    def _log(status, http_code, location_id=None, error_message=None):
        reqs = _load("api_requests.json")
        rid = _new_id("req")
        row = {
            "id": rid,
            "tool_name": "get_local_time",
            "location_raw": location if isinstance(location, str) else str(location),
            "location_id": location_id,
            "days": None,
            "hours": None,
            "limit": None,
            "severity": None,
            "response_status_code": http_code,
            "cache_hit": False,
            "served_weather_product_id": None,
            "latency_ms": int(max(0, round((time.time() - t0) * 1000))),
            "status": status,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now,
        }
        reqs.append(row)
        _save("api_requests.json", reqs)

    def _parse_coords(s):
        if not isinstance(s, str):
            return None
        m = re.match(r"^\s*-?\d+(\.\d+)?\s*,\s*-?\d+(\.\d+)?\s*$", s)
        if not m:
            return None
        parts = s.split(",")
        try:
            lat = float(parts[0].strip())
            lon = float(parts[1].strip())
        except ValueError:
            return None
        return lat, lon

    def _within_us(lat, lon):
        if (24.0 <= lat <= 49.8 and -125.0 <= lon <= -66.0):
            return True
        if (51.0 <= lat <= 71.5 and -170.0 <= lon <= -129.0):
            return True
        if (18.5 <= lat <= 22.6 and -160.5 <= lon <= -154.5):
            return True
        if (17.5 <= lat <= 18.7 and -67.5 <= lon <= -64.2):
            return True
        if (13.0 <= lat <= 20.6 and 144.5 <= lon <= 146.5):
            return True
        if (-15.0 <= lat <= -10.0 and -171.5 <= lon <= -167.0):
            return True
        if (1.0 <= lat <= 10.5 and 131.0 <= lon <= 163.5):
            return True
        return False

    coords = _parse_coords(location)
    if not coords:
        _log("rejected", 400, error_message="Malformed coordinates. Expected 'lat,lng'.")
        return _err("VALIDATION_ERROR", "Malformed coordinates. Expected 'lat,lng'.")
    lat, lon = coords
    if not (-90.0 <= lat <= 90.0 and -180.0 <= lon <= 180.0):
        _log("rejected", 400, error_message="Coordinates out of range.")
        return _err("VALIDATION_ERROR", "Coordinates out of range.")
    if not _within_us(lat, lon):
        _log("rejected", 400, error_message="Coordinates not within supported US boundaries.")
        return _err("VALIDATION_ERROR", "Coordinates not within supported US boundaries.")

    # Resolve location row; must have timezone present or fail (resolvable-location error)
    locations = _load("locations.json")
    input_raw_norm = f"{lat:.6f},{lon:.6f}"
    loc = None
    for r in locations:
        if r.get("source") in ("coordinates", "derived_from_coordinates") and r.get("input_location_raw") == input_raw_norm:
            loc = r
            break
    if not loc:
        # try by numeric match if older formatting differs
        for r in locations:
            if r.get("latitude") is None or r.get("longitude") is None:
                continue
            try:
                if abs(float(r.get("latitude")) - lat) < 1e-6 and abs(float(r.get("longitude")) - lon) < 1e-6:
                    loc = r
                    break
            except Exception:
                continue

    if not loc:
        _log("failed", 404, error_message="Location could not be resolved to a supported timezone.")
        return _err("NOT_FOUND", "Location could not be resolved to a supported timezone.")

    if loc.get("status") == "blocked":
        _log("failed", 404, location_id=loc.get("id"), error_message="Location is blocked.")
        return _err("NOT_FOUND", "Location cannot be used.")

    tz = loc.get("timezone")
    if not isinstance(tz, str) or "/" not in tz:
        _log("failed", 404, location_id=loc.get("id"), error_message="Timezone missing for resolved location.")
        return _err("NOT_FOUND", "Timezone missing for resolved location.", location_id=loc.get("id"))

    try:
        from zoneinfo import ZoneInfo
        local_dt = now_dt.replace(tzinfo=datetime.timezone.utc).astimezone(ZoneInfo(tz))
        local_iso = local_dt.isoformat()
    except Exception:
        _log("failed", 404, location_id=loc.get("id"), error_message="Unsupported timezone for resolved location.")
        return _err("NOT_FOUND", "Unsupported timezone for resolved location.", timezone=tz)

    # Touch updated_at
    loc["updated_at"] = now
    _save("locations.json", locations)

    _log("succeeded", 200, location_id=loc.get("id"))
    return {
        "location_id": loc.get("id"),
        "timezone": tz,
        "utc_now": now,
        "local_time": local_iso,
    }

def resolve_location(location, source=None, create_if_missing=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0026000" if __import__("os").path.isdir("./environment_mix/0026000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{os.urandom(6).hex()}"

    def _parse_coords(s):
        if not isinstance(s, str):
            return None
        m = re.match(r"^\s*-?\d+(\.\d+)?\s*,\s*-?\d+(\.\d+)?\s*$", s)
        if not m:
            return None
        parts = s.split(",")
        try:
            lat = float(parts[0].strip())
            lon = float(parts[1].strip())
        except ValueError:
            return None
        return lat, lon

    allowed_states = set(["AL","AK","AS","AR","AZ","CA","CO","CT","DE","DC","FL","GA","GU","HI","ID","IL","IN","IA","KS","KY","LA","ME","MD","MA","MI","MN","MS","MO","MT","NE","NV","NH","NJ","NM","NY","NC","ND","OH","OK","OR","PA","PR","RI","SC","SD","TN","TX","UT","VT","VI","VA","WA","WV","WI","WY","MP","PW","FM","MH"])
    def _within_us(lat, lon):
        if (24.0 <= lat <= 49.8 and -125.0 <= lon <= -66.0):
            return True
        if (51.0 <= lat <= 71.5 and -170.0 <= lon <= -129.0):
            return True
        if (18.5 <= lat <= 22.6 and -160.5 <= lon <= -154.5):
            return True
        if (17.5 <= lat <= 18.7 and -67.5 <= lon <= -64.2):
            return True
        if (13.0 <= lat <= 20.6 and 144.5 <= lon <= 146.5):
            return True
        if (-15.0 <= lat <= -10.0 and -171.5 <= lon <= -167.0):
            return True
        if (1.0 <= lat <= 10.5 and 131.0 <= lon <= 163.5):
            return True
        return False

    def _log(status, http_code, location_id=None, error_message=None):
        reqs = _load("api_requests.json")
        rid = _new_id("req")
        row = {
            "id": rid,
            "tool_name": "get_current_weather",  # closest tool_name enum; no resolve_location in log schema
            "location_raw": location if isinstance(location, str) else str(location),
            "location_id": location_id,
            "days": None,
            "hours": None,
            "limit": None,
            "severity": None,
            "response_status_code": http_code,
            "cache_hit": False,
            "served_weather_product_id": None,
            "latency_ms": int(max(0, round((time.time() - t0) * 1000))),
            "status": status,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now,
        }
        reqs.append(row)
        _save("api_requests.json", reqs)

    # defaults
    if source is None:
        source = "user"
    if create_if_missing is None:
        create_if_missing = True

    if source not in ("user", "client", "import", "system"):
        _log("rejected", 400, error_message="Invalid source.")
        return _err("VALIDATION_ERROR", "Invalid source.", allowed=["user","client","import","system"])
    if not isinstance(create_if_missing, bool):
        _log("rejected", 400, error_message="create_if_missing must be boolean.")
        return _err("VALIDATION_ERROR", "create_if_missing must be boolean.")

    if not isinstance(location, str) or not location.strip():
        _log("rejected", 400, error_message="location must be a non-empty string.")
        return _err("VALIDATION_ERROR", "location must be a non-empty string.")

    locs = _load("locations.json")

    coords = _parse_coords(location)
    if coords:
        lat, lon = coords
        if not (-90.0 <= lat <= 90.0 and -180.0 <= lon <= 180.0):
            _log("rejected", 400, error_message="Coordinates out of range.")
            return _err("VALIDATION_ERROR", "Coordinates out of range.")
        if not _within_us(lat, lon):
            _log("rejected", 400, error_message="Coordinates not within supported US boundaries.")
            return _err("VALIDATION_ERROR", "Coordinates not within supported US boundaries.")

        input_raw_norm = f"{lat:.6f},{lon:.6f}"
        # Use schema enum for locations.source; map caller source tag into input_location_raw provenance only.
        src = "coordinates"
        found = None
        for r in locs:
            if r.get("source") == src and r.get("input_location_raw") == input_raw_norm:
                found = r
                break
        if not found:
            if not create_if_missing:
                _log("failed", 404, error_message="Location not found.", location_id=None)
                return _err("NOT_FOUND", "Location not found.")
            new_row = {
                "id": _new_id("loc"),
                "source": src,
                "input_location_raw": input_raw_norm,
                "latitude": lat,
                "longitude": lon,
                "state_code": None,
                "timezone": None,
                "coverage_type": "unknown",
                "status": "active",
                "created_at": now,
                "updated_at": now,
            }
            # uniqueness(source, input_location_raw)
            for r in locs:
                if r.get("source") == new_row["source"] and r.get("input_location_raw") == new_row["input_location_raw"]:
                    found = r
                    break
            if not found:
                locs.append(new_row)
                _save("locations.json", locs)
                found = new_row
        else:
            found["updated_at"] = now
            _save("locations.json", locs)

        if found.get("status") == "blocked":
            _log("failed", 404, location_id=found.get("id"), error_message="Location is blocked.")
            return _err("NOT_FOUND", "Location cannot be used.")
        _log("succeeded", 200, location_id=found.get("id"))
        return {"location": found}

    # state code path
    state = location.strip().upper()
    if len(state) != 2 or state not in allowed_states:
        _log("rejected", 400, error_message="Invalid state/territory code.")
        return _err("VALIDATION_ERROR", "Invalid state/territory code.")
    src = "state_code"
    found = None
    for r in locs:
        if r.get("source") == src and r.get("input_location_raw") == state:
            found = r
            break
    if not found:
        if not create_if_missing:
            _log("failed", 404, error_message="Location not found.")
            return _err("NOT_FOUND", "Location not found.")
        new_row = {
            "id": _new_id("loc"),
            "source": src,
            "input_location_raw": state,
            "latitude": None,
            "longitude": None,
            "state_code": state,
            "timezone": None,
            "coverage_type": "state" if state not in ("AS","GU","MP","PR","VI","PW","FM","MH") else "territory",
            "status": "active",
            "created_at": now,
            "updated_at": now,
        }
        for r in locs:
            if r.get("source") == new_row["source"] and r.get("input_location_raw") == new_row["input_location_raw"]:
                found = r
                break
        if not found:
            locs.append(new_row)
            _save("locations.json", locs)
            found = new_row
    else:
        found["updated_at"] = now
        _save("locations.json", locs)

    if found.get("status") == "blocked":
        _log("failed", 404, location_id=found.get("id"), error_message="Location is blocked.")
        return _err("NOT_FOUND", "Location cannot be used.")
    _log("succeeded", 200, location_id=found.get("id"))
    return {"location": found}

