    def _new_id(prefix):
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{os.urandom(6).hex()}"

    def _log(status, http_code, location_id=None, error_message=None, cache_hit=False, served_weather_product_id=None, days_v=None, hours_v=None, severity_v=None):
        reqs = _load("api_requests.json")
        rid = _new_id("req")
        row = {
            "id": rid,
            "tool_name": "get_current_weather",  # closest tool_name enum; refresh not listed
            "location_raw": location if isinstance(location, str) else str(location),
            "location_id": location_id,
            "days": days_v,
            "hours": hours_v,
            "limit": None,
            "severity": severity_v,
            "response_status_code": http_code,
            "cache_hit": bool(cache_hit),
            "served_weather_product_id": served_weather_product_id,
            "latency_ms": int(max(0, round((time.time() - t0) * 1000))),
            "status": status,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now,
        }
        reqs.append(row)
        _save("api_requests.json", reqs)

    def _parse_coords(s):
        if not isinstance(s, str):
            return None
        m = re.match(r"^\s*-?\d+(\.\d+)?\s*,\s*-?\d+(\.\d+)?\s*$", s)
        if not m:
            return None
        parts = s.split(",")
        try:
            lat = float(parts[0].strip())
            lon = float(parts[1].strip())
        except ValueError:
            return None
        return lat, lon

    allowed_states = set(["AL","AK","AS","AR","AZ","CA","CO","CT","DE","DC","FL","GA","GU","HI","ID","IL","IN","IA","KS","KY","LA","ME","MD","MA","MI","MN","MS","MO","MT","NE","NV","NH","NJ","NM","NY","NC","ND","OH","OK","OR","PA","PR","RI","SC","SD","TN","TX","UT","VT","VI","VA","WA","WV","WI","WY","MP","PW","FM","MH"])

    def _within_us(lat, lon):
        if (24.0 <= lat <= 49.8 and -125.0 <= lon <= -66.0):
            return True
        if (51.0 <= lat <= 71.5 and -170.0 <= lon <= -129.0):
            return True
        if (18.5 <= lat <= 22.6 and -160.5 <= lon <= -154.5):
            return True
        if (17.5 <= lat <= 18.7 and -67.5 <= lon <= -64.2):
            return True
        if (13.0 <= lat <= 20.6 and 144.5 <= lon <= 146.5):
            return True
        if (-15.0 <= lat <= -10.0 and -171.5 <= lon <= -167.0):
            return True
        if (1.0 <= lat <= 10.5 and 131.0 <= lon <= 163.5):
            return True
        return False

    def _parse_time(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    # Validate kinds
    if not isinstance(kinds, list) or len(kinds) < 1:
        _log("rejected", 400, error_message="kinds must be a non-empty array.", days_v=None, hours_v=None, severity_v=None)
        return _err("VALIDATION_ERROR", "kinds must be a non-empty array.")
    allowed_kinds = {"current", "forecast_daily", "forecast_hourly", "alerts"}
    for k in kinds:
        if k not in allowed_kinds:
            _log("rejected", 400, error_message="Invalid kind in kinds.", days_v=None, hours_v=None, severity_v=None)
            return _err("VALIDATION_ERROR", "Invalid kind in kinds.", allowed=sorted(list(allowed_kinds)))

    # defaults and validation for days/hours/severity/force
    if force is None:
        force = False
    if not isinstance(force, bool):
        _log("rejected", 400, error_message="force must be boolean.")
        return _err("VALIDATION_ERROR", "force must be boolean.")

    if days is None:
        days_v = 7
    else:
        if not isinstance(days, int) or isinstance(days, bool):
            _log("rejected", 400, error_message="days must be an integer 1..7.")
            return _err("VALIDATION_ERROR", "days must be an integer 1..7.")
        days_v = days
    if days_v < 1 or days_v > 7:
        _log("rejected", 400, error_message="days must be between 1 and 7.", days_v=days_v)
        return _err("VALIDATION_ERROR", "days must be between 1 and 7.")

    if hours is None:
        hours_v = 24
    else:
        if not isinstance(hours, int) or isinstance(hours, bool):
            _log("rejected", 400, error_message="hours must be an integer 1..48.")
            return _err("VALIDATION_ERROR", "hours must be an integer 1..48.")
        hours_v = hours
    if hours_v < 1 or hours_v > 48:
        _log("rejected", 400, error_message="hours must be between 1 and 48.", hours_v=hours_v)
        return _err("VALIDATION_ERROR", "hours must be between 1 and 48.")

    if severity is None:
        severity_v = "all"
    else:
        if severity not in ("all", "extreme", "severe", "moderate", "minor"):
            _log("rejected", 400, error_message="Invalid severity.", severity_v=str(severity))
            return _err("VALIDATION_ERROR", "Invalid severity.", allowed=["all","extreme","severe","moderate","minor"])
        severity_v = severity

    # Resolve location (coordinates or state code)
    location_id = None
    loc_row = None
    coords = _parse_coords(location) if isinstance(location, str) else None
    locs = _load("locations.json")

    if coords:
        lat, lon = coords
        if not (-90.0 <= lat <= 90.0 and -180.0 <= lon <= 180.0):
            _log("rejected", 400, error_message="Coordinates out of range.", days_v=days_v, hours_v=hours_v, severity_v=severity_v)
            return _err("VALIDATION_ERROR", "Coordinates out of range.")
        if not _within_us(lat, lon):
            _log("rejected", 400, error_message="Coordinates not within supported US boundaries.", days_v=days_v, hours_v=hours_v, severity_v=severity_v)
            return _err("VALIDATION_ERROR", "Coordinates not within supported US boundaries.")
        input_raw_norm = f"{lat:.6f},{lon:.6f}"
        for r in locs:
            if r.get("source") in ("coordinates", "derived_from_coordinates") and r.get("input_location_raw") == input_raw_norm:
                loc_row = r
                break
        if not loc_row:
            loc_row = {
                "id": _new_id("loc"),
                "source": "derived_from_coordinates",
                "input_location_raw": input_raw_norm,
                "latitude": lat,
                "longitude": lon,
                "state_code": None,
                "timezone": None,
                "coverage_type": "unknown",
                "status": "active",
                "created_at": now,
                "updated_at": now,
            }
            locs.append(loc_row)
            _save("locations.json", locs)
    else:
        if not isinstance(location, str):
            _log("rejected", 400, error_message="location must be a string.", days_v=days_v, hours_v=hours_v, severity_v=severity_v)
            return _err("VALIDATION_ERROR", "location must be a string.")
        state = location.strip().upper()
        if len(state) != 2 or state not in allowed_states:
            _log("rejected", 400, error_message="Invalid state/territory code.", days_v=days_v, hours_v=hours_v, severity_v=severity_v)
            return _err("VALIDATION_ERROR", "Invalid state/territory code.")
        for r in locs:
            if r.get("source") == "state_code" and r.get("input_location_raw") == state:
                loc_row = r
                break
        if not loc_row:
            loc_row = {
                "id": _new_id("loc"),
                "source": "state_code",
                "input_location_raw": state,
                "latitude": None,
                "longitude": None,
                "state_code": state,
                "timezone": None,
                "coverage_type": "state" if state not in ("AS","GU","MP","PR","VI","PW","FM","MH") else "territory",
                "status": "active",
                "created_at": now,
                "updated_at": now,
            }
            locs.append(loc_row)
            _save("locations.json", locs)

    if loc_row.get("status") == "blocked":
        _log("failed", 404, location_id=loc_row.get("id"), error_message="Location is blocked.", days_v=days_v, hours_v=hours_v, severity_v=severity_v)
        return _err("NOT_FOUND", "Location cannot be used.")
    location_id = loc_row.get("id")

    # Select/cache products for immediate return; refresh is simulated by marking stale->fresh when forced or expiring not available.
    products = _load("weather_products.json")

    def _variant_for(kind):
        if kind == "current":
            return None
        if kind == "forecast_daily":
            return f"days={days_v}"
        if kind == "forecast_hourly":
            return f"hours={hours_v}"
        if kind == "alerts":
            return f"severity={severity_v}"
        return None

    def _is_fresh(p):
        if p.get("status") != "fresh":
            return False
        exp = _parse_time(p.get("expires_at"))
        if exp is None:
            return True
        return exp > now_dt

    def _pick_best(cands):
        # Prefer fresh unexpired newest fetched_at; else stale newest; else expired newest; else error newest.
        def _key(p):
            ft = _parse_time(p.get("fetched_at")) or datetime.datetime(1970, 1, 1)
            return ft
        fresh = [p for p in cands if _is_fresh(p)]
        if fresh:
            fresh.sort(key=_key, reverse=True)
            return fresh[0], True
        non_error = [p for p in cands if p.get("status") != "error"]
        if non_error:
            # prefer stale over expired if both exist by status weight, then fetched_at
            weight = {"stale": 2, "expired": 1, "fresh": 3}
            non_error.sort(key=lambda p: (weight.get(p.get("status"), 0), _key(p)), reverse=True)
            return non_error[0], False
        if cands:
            cands.sort(key=_key, reverse=True)
            return cands[0], False
        return None, False

    served = {}
    any_cache_hit = False
    served_any_product_id = None
    refreshed = []

    # For each kind, decide whether to "refresh" by flipping/creating placeholder product row.
    for kind in kinds:
        variant = _variant_for(kind)
        cands = [p for p in products if p.get("location_id") == location_id and p.get("kind") == kind and p.get("variant") == variant]
        best, hit = _pick_best(cands)
        if best:
            served[kind] = best
            any_cache_hit = any_cache_hit or hit
            served_any_product_id = served_any_product_id or best.get("id")
        # Decide refresh necessity
        needs_refresh = force
        if not needs_refresh:
            # refresh when no fresh unexpired exists
            if not any(p for p in cands if _is_fresh(p)):
                needs_refresh = True
        if needs_refresh:
            # Simulate enqueue by updating/creating a row with fetched_at now and expires_at + 30m, status fresh, keep payload if exists.
            # Must respect unique(location_id, kind, variant): update existing if present else create.
            target = None
            if cands:
                # choose newest by fetched_at
                def _ft(p): return _parse_time(p.get("fetched_at")) or datetime.datetime(1970, 1, 1)
                cands.sort(key=_ft, reverse=True)
                target = cands[0]
            expires = (now_dt + datetime.timedelta(minutes=30)).isoformat() + "Z"
            if target:
                # legal transitions enforced
                old = target.get("status")
                new = "fresh"
                allowed = {
                    "fresh": ["stale", "expired", "error"],
                    "stale": ["fresh", "expired", "error"],
                    "expired": ["fresh", "error"],
                    "error": ["fresh", "stale", "expired"],
                }
                if old not in allowed or new not in allowed.get(old, []) and old != new:
                    _log("failed", 409, location_id=location_id, error_message="Invalid product status transition.", days_v=days_v, hours_v=hours_v, severity_v=severity_v)
                    return _err("INVALID_TRANSITION", "Invalid product status transition.", from_status=old, to_status=new)
                target["status"] = "fresh"
                target["error_message"] = None
                target["fetched_at"] = now
                target["expires_at"] = expires
                target["updated_at"] = now
                if not isinstance(target.get("payload"), dict):
                    target["payload"] = {"note": "refreshed", "kind": kind, "variant": variant}
                refreshed.append({"kind": kind, "variant": variant, "weather_product_id": target.get("id"), "refreshed": True})
            else:
                new_row = {
                    "id": _new_id("wp"),
                    "location_id": location_id,
                    "kind": kind,
                    "variant": variant,
                    "provider": "NWS",
                    "provider_ref": None,
                    "issued_at": None,
                    "valid_from": None,
                    "valid_to": None,
                    "fetched_at": now,
                    "expires_at": expires,
                    "payload": {"note": "refreshed", "kind": kind, "variant": variant},
                    "status": "fresh",
                    "error_message": None,
                    "created_at": now,
                    "updated_at": now,
                }
                products.append(new_row)
                refreshed.append({"kind": kind, "variant": variant, "weather_product_id": new_row["id"], "refreshed": True})
                if kind not in served:
                    served[kind] = new_row

    _save("weather_products.json", products)
    # touch location
    loc_row["updated_at"] = now
    _save("locations.json", locs)

    _log("succeeded", 200, location_id=location_id, cache_hit=any_cache_hit, served_weather_product_id=served_any_product_id, days_v=days_v, hours_v=hours_v, severity_v=severity_v)
    # Return latest served products (not necessarily all kinds exist; but we ensured served on create)
    resp_products = []
    for kind in kinds:
        wp = served.get(kind)
        if wp:
            resp_products.append(wp)

    return {
        "location": {"id": location_id, "source": loc_row.get("source"), "input_location_raw": loc_row.get("input_location_raw")},
        "requested_kinds": kinds,
        "variants": {
            "forecast_daily": f"days={days_v}" if "forecast_daily" in kinds else None,
            "forecast_hourly": f"hours={hours_v}" if "forecast_hourly" in kinds else None,
            "alerts": f"severity={severity_v}" if "alerts" in kinds else None,
        },
        "refresh": {
            "force": bool(force),
            "refreshed": refreshed,
        },
        "products": resp_products,
    }

def list_api_requests(tool_name=None, status=None, location_id=None, response_status_code=None, cache_hit=None, limit=None, cursor=None, start_at=None, end_at=None, **_extra):
    import json, os, datetime, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0026000" if __import__("os").path.isdir("./environment_mix/0026000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        st = s.strip()
        try:
            if st.endswith("Z"):
                st = st[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(st)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    def _get_field_dt(row, key):
        v = row.get(key)
        if isinstance(v, datetime.datetime):
            dt = v
        elif isinstance(v, str):
            dt = _parse_rfc3339(v)
        else:
            dt = None
        if dt is None:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _log_api_request(status_value, http_code, error_message=None, latency_ms=None):
        reqs = _load("api_requests.json")
        now = _now_utc()
        rid = "req_" + now.strftime("%Y%m%d%H%M%S%f")
        row = {
            "id": rid,
            "tool_name": "list_api_requests",
            "location_raw": "",
            "location_id": None,
            "days": None,
            "hours": None,
            "limit": int(limit) if isinstance(limit, int) else None,
            "severity": None,
            "response_status_code": int(http_code) if http_code is not None else None,
            "cache_hit": False,
            "served_weather_product_id": None,
            "latency_ms": int(latency_ms) if isinstance(latency_ms, int) else None,
            "status": status_value,
            "error_message": error_message,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        reqs.append(row)
        _save("api_requests.json", reqs)
        return row

    start_clock = datetime.datetime.now(datetime.timezone.utc)

    # Validate inputs
    allowed_tools = {"get_current_weather", "get_weather_forecast", "get_hourly_forecast", "get_weather_alerts", "find_weather_stations", "get_local_time", "list_api_requests", "get_api_request", "update_location_status", "get_whoami"}
    allowed_status = {"succeeded", "failed", "rejected"}

    if tool_name is not None and (not isinstance(tool_name, str) or not tool_name.strip()):
        _log_api_request("rejected", 400, "tool_name must be a non-empty string", 0)
        return _err("VALIDATION_ERROR", "tool_name must be a non-empty string")
    if tool_name is not None and tool_name not in allowed_tools:
        _log_api_request("rejected", 400, "tool_name is not recognized", 0)
        return _err("VALIDATION_ERROR", "tool_name is not recognized", allowed=list(sorted(allowed_tools)))

    if status is not None and status not in allowed_status:
        _log_api_request("rejected", 400, "status must be one of: succeeded, failed, rejected", 0)
        return _err("VALIDATION_ERROR", "status must be one of: succeeded, failed, rejected")

    if location_id is not None and (not isinstance(location_id, str) or not location_id.strip()):
        _log_api_request("rejected", 400, "location_id must be a non-empty string", 0)
        return _err("VALIDATION_ERROR", "location_id must be a non-empty string")

    if response_status_code is not None:
        if not isinstance(response_status_code, int):
            _log_api_request("rejected", 400, "response_status_code must be an integer", 0)
            return _err("VALIDATION_ERROR", "response_status_code must be an integer")
        if response_status_code < 100 or response_status_code > 599:
            _log_api_request("rejected", 400, "response_status_code must be between 100 and 599", 0)
            return _err("VALIDATION_ERROR", "response_status_code must be between 100 and 599")

    if cache_hit is not None and not isinstance(cache_hit, bool):
        _log_api_request("rejected", 400, "cache_hit must be a boolean", 0)
        return _err("VALIDATION_ERROR", "cache_hit must be a boolean")

    if limit is None:
        limit_v = 50
    else:
        if not isinstance(limit, int):
            _log_api_request("rejected", 400, "limit must be an integer", 0)
            return _err("VALIDATION_ERROR", "limit must be an integer")
        if limit < 1 or limit > 100:
            _log_api_request("rejected", 400, "limit must be between 1 and 100", 0)
            return _err("VALIDATION_ERROR", "limit must be between 1 and 100")
        limit_v = limit

    start_dt = None
    end_dt = None
    if start_at is not None:
        if not isinstance(start_at, str):
            _log_api_request("rejected", 400, "start_at must be an RFC3339 date-time string", 0)
            return _err("VALIDATION_ERROR", "start_at must be an RFC3339 date-time string")
        start_dt = _parse_rfc3339(start_at)
        if start_dt is None:
            _log_api_request("rejected", 400, "start_at must be an RFC3339 date-time string", 0)
            return _err("VALIDATION_ERROR", "start_at must be an RFC3339 date-time string")
    if end_at is not None:
        if not isinstance(end_at, str):
            _log_api_request("rejected", 400, "end_at must be an RFC3339 date-time string", 0)
            return _err("VALIDATION_ERROR", "end_at must be an RFC3339 date-time string")
        end_dt = _parse_rfc3339(end_at)
        if end_dt is None:
            _log_api_request("rejected", 400, "end_at must be an RFC3339 date-time string", 0)
            return _err("VALIDATION_ERROR", "end_at must be an RFC3339 date-time string")

    if start_dt is not None and end_dt is not None and end_dt < start_dt:
        _log_api_request("rejected", 400, "end_at must be greater than or equal to start_at", 0)
        return _err("VALIDATION_ERROR", "end_at must be greater than or equal to start_at")

    # Cursor decoding: expects base64url of JSON {"offset": int}
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor.strip():
            _log_api_request("rejected", 400, "cursor must be a non-empty string", 0)
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string")
        try:
            pad = "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict) or "offset" not in obj or not isinstance(obj["offset"], int) or obj["offset"] < 0:
                _log_api_request("rejected", 400, "cursor is invalid", 0)
                return _err("VALIDATION_ERROR", "cursor is invalid")
            offset = obj["offset"]
        except (ValueError, json.JSONDecodeError):
            _log_api_request("rejected", 400, "cursor is invalid", 0)
            return _err("VALIDATION_ERROR", "cursor is invalid")

    # Read + filter
    reqs = _load("api_requests.json")

    filtered = []
    for r in reqs:
        if tool_name is not None and r.get("tool_name") != tool_name:
            continue
        if status is not None and r.get("status") != status:
            continue
        if location_id is not None and r.get("location_id") != location_id:
            continue
        if response_status_code is not None and r.get("response_status_code") != response_status_code:
            continue
        if cache_hit is not None and r.get("cache_hit") != cache_hit:
            continue
        if start_dt is not None:
            cdt = _get_field_dt(r, "created_at")
            if cdt is None or cdt < start_dt:
                continue
        if end_dt is not None:
            cdt = _get_field_dt(r, "created_at")
            if cdt is None or cdt >= end_dt:
                continue
        filtered.append(r)

    # Sort by created_at desc; unknown created_at sorts last
    def _sort_key(r):
        dt = _get_field_dt(r, "created_at")
        if dt is None:
            dt = datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return dt

    filtered.sort(key=_sort_key, reverse=True)

    total = len(filtered)
    page = filtered[offset: offset + limit_v]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        payload = json.dumps({"offset": next_offset}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    latency_ms = int((datetime.datetime.now(datetime.timezone.utc) - start_clock).total_seconds() * 1000)
    _log_api_request("succeeded", 200, None, latency_ms)

    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit_v,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
    }

def get_api_request(id, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0026000" if __import__("os").path.isdir("./environment_mix/0026000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return _now_utc().isoformat().replace("+00:00", "Z")

    def _coerce_rows(x):
        if isinstance(x, list):
            return x, "list"
        if isinstance(x, dict) and isinstance(x.get("rows"), list):
            return x["rows"], "dict_rows"
        return [], "list"

    def _gen_id(prefix):
        # deterministic-enough id without non-stdlib dependencies
        now = _now_utc()
        ms = int(now.timestamp() * 1000)
        sub = int((time.time_ns() // 1000) % 1000000)
        return f"{prefix}_{ms:013d}{sub:06d}"

    def _append_api_request(reqs_raw, shape, row):
        reqs, _ = _coerce_rows(reqs_raw)
        reqs.append(row)
        if shape == "dict_rows" and isinstance(reqs_raw, dict):
            reqs_raw["rows"] = reqs
            _save("api_requests.json", reqs_raw)
        else:
            _save("api_requests.json", reqs)

    t0 = time.time()
    now = _now_utc()

    # Validate input
    if not isinstance(id, str) or not id.strip():
        latency_ms = int((time.time() - t0) * 1000)
        reqs_raw = _load("api_requests.json")
        _, shape = _coerce_rows(reqs_raw)
        _append_api_request(
            reqs_raw,
            shape,
            {
                "id": _gen_id("uswx_req"),
                "tool_name": "get_api_request",
                "location_raw": "",
                "location_id": None,
                "days": None,
                "hours": None,
                "limit": None,
                "severity": None,
                "response_status_code": 400,
                "cache_hit": False,
                "served_weather_product_id": None,
                "latency_ms": latency_ms,
                "status": "rejected",
                "error_message": "id must be a non-empty string",
                "created_at": _iso(now),
                "updated_at": _iso(now),
            },
        )
        return _err("VALIDATION_ERROR", "id must be a non-empty string", id=id)

    req_id = id.strip()

    # Fetch
    api_requests_raw = _load("api_requests.json")
    api_requests, shape = _coerce_rows(api_requests_raw)

    found = None
    if isinstance(api_requests, list):
        for r in api_requests:
            if isinstance(r, dict) and r.get("id") == req_id:
                found = r
                break

    # Log this tool invocation (reads included), per business rules
    latency_ms = int((time.time() - t0) * 1000)
    status = "succeeded" if found is not None else "failed"
    response_status_code = 200 if found is not None else 404
    error_message = None if found is not None else "api_requests record not found"

    _append_api_request(
        api_requests_raw,
        shape,
        {
            "id": _gen_id("uswx_req"),
            "tool_name": "get_api_request",
            # tool has no "location" parameter; store id in location_raw to preserve caller input
            "location_raw": req_id,
            "location_id": None,
            "days": None,
            "hours": None,
            "limit": None,
            "severity": None,
            "response_status_code": response_status_code,
            "cache_hit": False,
            "served_weather_product_id": None,
            "latency_ms": latency_ms,
            "status": status,
            "error_message": error_message,
            "created_at": _iso(_now_utc()),
            "updated_at": _iso(_now_utc()),
        },
    )

    if found is None:
        return _err("NOT_FOUND", "api_requests record not found", id=req_id)

    # Return stored record as-is (no fabrication), with a minimal envelope
    return {"api_request": found}

def update_location_status(id, status, reason=None, **_extra):
    import json, os, datetime

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0026000" if __import__("os").path.isdir("./environment_mix/0026000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _log_api_request(status_value, http_code, error_message=None, location_raw_val="", location_id_val=None, latency_ms=None):
        reqs = _load("api_requests.json")
        now = _now_utc()
        rid = "req_" + now.strftime("%Y%m%d%H%M%S%f")
        row = {
            "id": rid,
            "tool_name": "update_location_status",
            "location_raw": location_raw_val,
            "location_id": location_id_val,
            "days": None,
            "hours": None,
            "limit": None,
            "severity": None,
            "response_status_code": int(http_code) if http_code is not None else None,
            "cache_hit": False,
            "served_weather_product_id": None,
            "latency_ms": int(latency_ms) if isinstance(latency_ms, int) else None,
            "status": status_value,
            "error_message": error_message,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        reqs.append(row)
        _save("api_requests.json", reqs)
        return row

    start_clock = datetime.datetime.now(datetime.timezone.utc)

    if not isinstance(id, str) or not id.strip():
        _log_api_request("rejected", 400, "id must be a non-empty string", latency_ms=0)
        return _err("VALIDATION_ERROR", "id must be a non-empty string")
    if not isinstance(status, str) or status not in {"active", "inactive", "blocked"}:
        _log_api_request("rejected", 400, "status must be one of: active, inactive, blocked", location_id_val=id, latency_ms=0)
        return _err("VALIDATION_ERROR", "status must be one of: active, inactive, blocked")
    if reason is not None and (not isinstance(reason, str) or not reason.strip()):
        _log_api_request("rejected", 400, "reason must be a non-empty string when provided", location_id_val=id, latency_ms=0)
        return _err("VALIDATION_ERROR", "reason must be a non-empty string when provided")

    locs = _load("locations.json")
    idx = None
    for i, r in enumerate(locs):
        if r.get("id") == id:
            idx = i
            break

    if idx is None:
        latency_ms = int((datetime.datetime.now(datetime.timezone.utc) - start_clock).total_seconds() * 1000)
        _log_api_request("failed", 404, "locations record not found", location_id_val=id, latency_ms=latency_ms)
        return _err("NOT_FOUND", "locations record not found", id=id)

    current = locs[idx]
    cur_status = current.get("status")
    transitions = {
        "active": {"inactive", "blocked"},
        "inactive": {"active", "blocked"},
        "blocked": {"inactive"},
    }
    if cur_status not in transitions:
        latency_ms = int((datetime.datetime.now(datetime.timezone.utc) - start_clock).total_seconds() * 1000)
        _log_api_request("failed", 409, "current location status is invalid", location_id_val=id, latency_ms=latency_ms)
        return _err("CONFLICT", "current location status is invalid", current_status=cur_status)

    if status == cur_status:
        # Idempotent: no mutation would violate "no success without effect"? Here we treat as conflict-free idempotent update,
        # but must still have an effect; we only update updated_at (and optional reason) to produce a real change.
        now = _now_utc()
        current["updated_at"] = _iso(now)
        if reason is not None:
            current["status_reason"] = reason
        locs[idx] = current
        _save("locations.json", locs)
        latency_ms = int((datetime.datetime.now(datetime.timezone.utc) - start_clock).total_seconds() * 1000)
        _log_api_request("succeeded", 200, None, location_id_val=id, latency_ms=latency_ms)
        return {"data": current, "meta": {"idempotent": True}}

    if status not in transitions[cur_status]:
        latency_ms = int((datetime.datetime.now(datetime.timezone.utc) - start_clock).total_seconds() * 1000)
        _log_api_request("rejected", 409, "invalid lifecycle transition", location_id_val=id, latency_ms=latency_ms)
        return _err(
            "INVALID_TRANSITION",
            "invalid lifecycle transition",
            from_status=cur_status,
            to_status=status,
            allowed=sorted(list(transitions[cur_status])),
        )

    # Apply transition
    now = _now_utc()
    current["status"] = status
    current["updated_at"] = _iso(now)
    if reason is not None:
        current["status_reason"] = reason
    locs[idx] = current
    _save("locations.json", locs)

    latency_ms = int((datetime.datetime.now(datetime.timezone.utc) - start_clock).total_seconds() * 1000)
    _log_api_request("succeeded", 200, None, location_id_val=id, latency_ms=latency_ms)

    return {"data": current}

def get_whoami(api_key, **_extra):
    import json, os, datetime

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0026000" if __import__("os").path.isdir("./environment_mix/0026000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        ts = _now_utc().strftime("%y%m%d%H%M%S%f")
        return f"{prefix}_{ts}"

    def _coerce_list(x):
        if isinstance(x, list):
            return x
        if isinstance(x, dict) and "rows" in x and isinstance(x["rows"], list):
            return x["rows"]
        return []

    def _append_request_log(status_value, http_code, error_message=None, latency_ms=None):
        reqs_raw = _load("api_requests.json")
        reqs = _coerce_list(reqs_raw)

        now = _now_utc()
        row = {
            "id": _gen_id("uswx_req"),
            "tool_name": "get_whoami",
            "location_raw": "",
            "location_id": None,
            "days": None,
            "hours": None,
            "limit": None,
            "severity": None,
            "response_status_code": int(http_code) if http_code is not None else None,
            "cache_hit": False,
            "served_weather_product_id": None,
            "latency_ms": int(latency_ms) if isinstance(latency_ms, int) and latency_ms >= 0 else None,
            "status": status_value,
            "error_message": error_message,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        reqs.append(row)

        if isinstance(reqs_raw, dict) and "rows" in reqs_raw and isinstance(reqs_raw["rows"], list):
            reqs_raw["rows"] = reqs
            _save("api_requests.json", reqs_raw)
        else:
            _save("api_requests.json", reqs)

        return row

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _active_credential_for_key(key_value):
        """
        Authenticate against any plausible credential registry file if present.
        IMPORTANT: match against stored client-visible value or id, not hashes.
        If no registry exists, treat this as a self-contained service where the
        provided api_key is accepted (authenticated) and return minimal context.
        """
        candidates = []
        key_sources = [
            "api_keys.json",
            "credentials.json",
            "keys.json",
            "auth_keys.json",
            "access_keys.json",
        ]
        found_any_store = False

        for fn in key_sources:
            path = os.path.join(_DB, fn)
            if not os.path.exists(path):
                continue
            found_any_store = True
            data = _load(fn)
            rows = _coerce_list(data)
            for r in rows:
                if not isinstance(r, dict):
                    continue
                candidates.append((fn, r))

        # If there is no credential store at all, accept provided api_key as authenticated.
        if not found_any_store:
            return {"mode": "implicit", "credential": {"id": None, "api_key": key_value, "scopes": ["weather:read"]}}

        # Otherwise, try to match by common fields: id, api_key, key, token, value
        for fn, r in candidates:
            for fld in ("api_key", "key", "token", "value", "id"):
                if r.get(fld) == key_value:
                    # Check for obvious inactive/disabled flags if present
                    if r.get("status") in ("inactive", "disabled", "revoked"):
                        continue
                    if r.get("active") is False:
                        continue
                    return {"mode": "registry", "credential": r, "source_file": fn}

        return None

    start = _now_utc()

    if not isinstance(api_key, str) or not api_key.strip():
        latency_ms = int((_now_utc() - start).total_seconds() * 1000)
        _append_request_log("rejected", 401, "api_key must be a non-empty string", latency_ms)
        return _err("UNAUTHORIZED", "api_key is required")

    key_value = api_key.strip()
    auth = _active_credential_for_key(key_value)
    latency_ms = int((_now_utc() - start).total_seconds() * 1000)

    if auth is None:
        _append_request_log("rejected", 401, "invalid or unknown api_key", latency_ms)
        return _err("UNAUTHORIZED", "invalid or unknown api_key")

    # Compute simple rate usage from api_requests (observable dynamics)
    reqs = _coerce_list(_load("api_requests.json"))
    now = _now_utc()
    window_seconds = 60
    cutoff = now - datetime.timedelta(seconds=window_seconds)
    recent = 0
    for r in reqs:
        if not isinstance(r, dict):
            continue
        ts = _parse_dt(r.get("created_at"))
        if ts is None or ts < cutoff:
            continue
        recent += 1

    # No explicit rate-limit rules provided in schema; report usage only.
    who = {
        "authenticated": True,
        "api_key": key_value,
        "credential": auth.get("credential") if isinstance(auth, dict) else None,
        "scopes": (auth.get("credential", {}) or {}).get("scopes", ["weather:read"]) if isinstance(auth, dict) else ["weather:read"],
        "rate_limit": {
            "window_seconds": window_seconds,
            "requests_in_window": recent,
        },
        "response_status_code": 200,
    }

    _append_request_log("succeeded", 200, None, latency_ms)
    return who
